WITH history AS (
      SELECT b.mktcode,b.tgtcode,b.bizdate,b.highPrice AS high_current,MIN(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS high_min,MAX(b.highPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS high_max,b.closePrice AS close_current,MIN(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS close_min,MAX(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS close_max,b.lowPrice AS low_current,MIN(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS low_min,MAX(b.lowPrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS low_max FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-14'
    ), current_reference AS (SELECT * FROM history WHERE bizdate='2026-04-14'),
    feature AS (SELECT h.* FROM dsl_history_diag_a74e87700159.history_extrema_v1 h WHERE h.bizdate='2026-04-14' AND h.snapshot_id='stock-20060104-20260414-v1' AND h.manifest_sha256='306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95' AND h.registry_fingerprint='a460a741b13b2cea6066c7a973c246463d68c6eb083c07a50650ed8403f3ab17')
    SELECT COUNT(*) FROM current_reference w FULL OUTER JOIN feature f ON w.mktcode=f.mktcode AND w.tgtcode=f.tgtcode
    WHERE w.mktcode IS NULL OR f.mktcode IS NULL OR NOT(f.high_current <=> w.high_current) OR NOT(f.high_min <=> w.high_min) OR NOT(f.high_max <=> w.high_max) OR NOT(f.close_current <=> w.close_current) OR NOT(f.close_min <=> w.close_min) OR NOT(f.close_max <=> w.close_max) OR NOT(f.low_current <=> w.low_current) OR NOT(f.low_min <=> w.low_min) OR NOT(f.low_max <=> w.low_max);
